			{id=9256,title="Overview",body="Forgemaster Gog'duh hurls two greater elementals at the party in an attempt to buy time. \n\nWhen the Forgemaster is critically wounded, Magmolatus escapes from the furnace and engages the party. Magmolatus periodically calls in Molten Elementals to assist him."},
			{id=9257,title="Damage Dealers",body="$bullet;While Forgemaster Gog'duh is alive, defeat the elementals called into combat.\n$bullet;Interrupt Calamity's |cFF2959D3|Hspell:149997|h[Firestorm]|h|r to prevent heavy Fire damage.\n$bullet;While Magmolatus is active, kill Molten Elementals to avoid being overwhelmed."},
			{id=9258,title="Healers",body="$bullet;Dispel |cFF2959D3|Hspell:149975|h[Dancing Flames]|h|r and |cFF2959D3|Hspell:150032|h[Withering Flames]|h|r quickly to prevent them from spreading.\n$bullet;If uninterrupted, |cFF2959D3|Hspell:149997|h[Firestorm]|h|r can do a lot of damage to a large area!"},
			{id=9259,title="Tanks",body="$bullet;|cFF2959D3|Hspell:149941|h[Rough Smash]|h|r and |cFF2959D3|Hspell:150023|h[Slag Smash]|h|r both do high damage and stun players!\n$bullet;Molten Elementals are immobile and cannot be tanked."},
			{id=9292,title="Stage One: Frantic Forgemaster",body="Gog'duh assaults players with blasts of magma, pausing only to hastily conjure elementals in his defense."},
			{id=8620,title="Gog'duh"},
			{id=8630,title="Magma Barrage"},
			{id=8622,title="Ruination, Servant of the Earth"},
			{id=8624,title="Shatter Earth"},
			{id=8625,title="Rough Smash"},
			{id=8626,title="Calamity, Servant of the Flame"},
			{id=8627,title="Dancing Flames",body="$[!2\n\nIn Heroic Difficulty, Dancing Flames initially strikes two players.$]$[!8\n\nIn Challenge Mode, Dancing Flames initially strikes two players.$]"},
			{id=8628,title="Firestorm"},
			{id=8629,title="Scorch"},
			{id=9293,title="Stage Two: Menacing Magma",body="Once Gog'duh is badly injured, the powerful elemental Magmolatus escapes and begins to wreak havoc."},
			{id=8621,title="Magmolatus",body="Magmolatus assaults players with a fierce combination of earth and fire."},
			{id=8634,title="Withering Flames"},
			{id=10343,title="Choking Ashes"},
