	[959]={
		encounterID=959,
		instanceID=457,
		order=10,
		name="Blackhand",
		lore="A ruthless tyrant and fierce warrior, Blackhand is Warlord of the Blackrock clan, second only to Grommash in stature within the Iron Horde. Bathed in sweltering heat that few other mortals could withstand,  Blackhand oversees the operations of his Foundry from atop its Crucible, wielding his smoldering slag hammer to forge weapons of peerless quality.",
