			{id=9578,title="Throw Slag Bombs"},
			{id=9579,title="Shattering Smash"},
			{id=8818,title="Stage Three: Iron Crucible",body="The Iron Crucible has hardened over after the Black Furnace was destroyed."},
			{id=8819,title="Overheated"},
			{id=9580,title="Slag Eruption"},
			{id=9581,title="Marked for Death",body="Blackhand marks a target for death. After $156096d Blackhand will cast Impaling Throw at the target. While on the Iron Crucible Blackhand is empowered and Impaling Throw impacts all targets in a line."},
			{id=10744,title="Section 33"},
