		sections={
			{id=9264,title="Overview",body="Araknath stands in the center of a massive solarium, positioned to receive solar energy in the form of channeled beams that will heal Araknath if they are not intercepted."},
			{id=10702,title="Damage Dealers",body="$bullet;Stand in the path of the solar rays focused on Araknath to prevent |cFF2959D3|Hspell:154149|h[Energize]|h|r, but doing so will inflict damage."},
			{id=10703,title="Healers",body="$bullet;Stand in the path of the solar rays focused on Araknath to prevent |cFF2959D3|Hspell:154149|h[Energize]|h|r, but doing so will inflict damage.\n$bullet;Araknath's |cFF2959D3|Hspell:154135|h[Supernova]|h|r damages all players."},
			{id=10701,title="Tanks",body="$bullet;Avoid Araknath's |cFF2959D3|Hspell:154132|h[Fiery Smash]|h|r ability, which strikes with either the construct's left or right arm."},
