		sections={
			{id=9268,title="Overview",body="Rukhran summons Dawnwings to aid it in battle, each erupting in a |cFF2959D3|Hspell:1253416|h[Blaze of Glory]|h|r upon defeat.\n\nPeriodically, Rukhran unleashes |cFF2959D3|Hspell:159381|h[Searing Quills]|h|r, devastating all players in its line of sight across the platform."},
			{id=33947,title="Damage Dealers",body="$bullet;Dawnwings will fixate on a player until they are defeated.\n$bullet;|cFF2959D3|Hspell:159381|h[Searing Quills]|h|r inflicts heavy fire damage to players within line of sight.",difficultyIDs={1,2}},
			{id=10705,title="Damage Dealers",body="$bullet;Dawnwings will fixate on a player until they are defeated.\n$bullet;|cFF2959D3|Hspell:159381|h[Searing Quills]|h|r inflicts heavy fire damage to players within line of sight.\n$bullet; |cFF2959D3|Hspell:1253424|h[Smoldering Egg]|h|r caught in the blast of |cFF2959D3|Hspell:1253416|h[Blaze of Glory]|h|r will reawaken as a Dawnwing.",difficultyIDs={23}},
			{id=10706,title="Healers",body="$bullet;Dawnwings will fixate on a player until they are defeated.\n$bullet;|cFF2959D3|Hspell:159381|h[Searing Quills]|h|r inflicts heavy fire damage to players within line of sight.\n$bullet;Dawnwings inflict moderate damage to the group with |cFF2959D3|Hspell:1253368|h[Burning Pursuit]|h|r while active.",difficultyIDs={1,2}},
			{id=33948,title="Healers",body="$bullet;Dawnwings will fixate on a player until they are defeated.\n$bullet;|cFF2959D3|Hspell:159381|h[Searing Quills]|h|r inflicts heavy fire damage to players within line of sight.\n$bullet;Dawnwings inflict moderate damage to the group with |cFF2959D3|Hspell:1253368|h[Burning Pursuit]|h|r while active.",difficultyIDs={23}},
			{id=10704,title="Tanks",body="$bullet;Rukhran casts |cFF2959D3|Hspell:153898|h[Screech]|h|r when there are no players in melee range for an extended period.\n$bullet;|cFF2959D3|Hspell:159381|h[Searing Quills]|h|r inflicts heavy fire damage to players within line of sight.\n$bullet; |cFF2959D3|Hspell:1253519|h[Burning Claws]|h|r inflicts heavy fire damage."},
