		sections={
			{id=9272,title="Overview",body="High Sage Viryx calls down the powerful arakkoa focusing lens to scorch the ground beneath her foes."},
			{id=33952,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:154044|h[Lens Flare]|h|r focuses on a player and burns any player in its path.\n$bullet; |cFF2959D3|Hspell:153954|h[Cast Down]|h|r calls a Solar Zealot that picks up a random player and attempts to drop them over the edge of Skyreach.",difficultyIDs={1,2}},
			{id=10708,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:154044|h[Lens Flare]|h|r focuses on a random player and burns any player in its path while leaving behind |cFF2959D3|Hspell:154043|h[Blazing Ground]|h|r.\n$bullet; |cFF2959D3|Hspell:153954|h[Cast Down]|h|r calls a Solar Zealot that picks up a random player and attempts to drop them over the edge of Skyreach.",difficultyIDs={23}},
			{id=33953,title="Healers",body="$bullet;|cFF2959D3|Hspell:154044|h[Lens Flare]|h|r focuses on a player and burns any player in its path.\n$bullet; |cFF2959D3|Hspell:1253542|h[Scorching Ray]|h|r inflicts moderate damage over time to targeted players.",difficultyIDs={1,2}},
			{id=10709,title="Healers",body="$bullet;|cFF2959D3|Hspell:154044|h[Lens Flare]|h|r focuses on a random player and burns any player in its path while leaving behind |cFF2959D3|Hspell:154043|h[Blazing Ground]|h|r.\n$bullet; |cFF2959D3|Hspell:1253542|h[Scorching Ray]|h|r inflicts moderate damage over time to targeted players.",difficultyIDs={23}},
			{id=10707,title="Tanks",body="$bullet;High Sage Viryx's |cFF2959D3|Hspell:154396|h[Solar Burst]|h|r inflicts significant Fire damage to its target.\n$bullet; |cFF2959D3|Hspell:153954|h[Cast Down]|h|r calls a Solar Zealot that picks up a random player and attempts to drop them over the edge of Skyreach."},
