	[971]={
		encounterID=971,
		instanceID=477,
		order=2,
		name="The Butcher",
		lore="Born in the fetid Underbelly of Highmaul, this ogre may have once had a proper name, but it is long forgotten. Abused and beaten from his earliest days, the hardship only strengthened his body even as it broke his mind. Now there is not an ogre in Highmaul who will not give him a wide berth as he hacks away at slaughtered carcasses to pass his days.",
		dungeonEncounterID=1706,
		uiMapID=610,
		pin={x=0.5785,y=0.5507},
		difficultyIDs={14,15,16,17},
		npcIDs={87447},
		displayIDs={53855},
		loot={
			{itemID=113632,diffs={14,15,16},faction=-1},
			{itemID=113633,diffs={14,15,16},faction=-1},
			{itemID=116290,diffs={17},faction=-1},
