			{itemID=113638,diffs={14,15,16},faction=-1},
			{itemID=113606,diffs={14,15,16},faction=-1},
			{itemID=116230,diffs={17},faction=-1},
			{itemID=113607,diffs={14,15,16},faction=-1},
			{itemID=113608,diffs={14,15,16},faction=-1},
			{itemID=113609,diffs={14,15,16},faction=-1},
			{itemID=116361,diffs={17},faction=-1},
			{itemID=116297,diffs={17},faction=-1},
			{itemID=113610,diffs={14,15,16},faction=-1},
			{itemID=113611,diffs={14,15,16},faction=-1},
			{itemID=113612,diffs={14,15,16},faction=-1},
			{itemID=116209,diffs={17},faction=-1},
			{itemID=116281,diffs={17},faction=-1},
			{itemID=116026,diffs={17},faction=-1},
			{itemID=115998,diffs={17},faction=-1},
		},
		sections={
			{id=9288,title="Overview",body="The Butcher attacks relentlessly, hacking at his foes with his dual implements of destruction. His main abilities seek to target large clumps of enemies, and positioning is key to handling and overcoming his attacks."},
			{id=9290,title="Damage Dealers",body="$bullet;Players in melee range must form clumps of varying sizes throughout the fight to manage the Butcher's |cFF2959D3|Hspell:156157|h[Cleave]|h|r and allow |cFF2959D3|Hspell:156152|h[Gushing Wounds]|h|r to fade.\n$bullet;Players at range must clump in order to survive the Butcher's Bounding Cleave sequence."},
			{id=9291,title="Healers",body="$bullet;Groups that are struck by |cFF2959D3|Hspell:156157|h[Cleave]|h|r suffer periodic damage from |cFF2959D3|Hspell:156152|h[Gushing Wounds]|h|r, which can stack.\n$bullet;All players in the raid suffer Physical damage when the Butcher begins his Bounding Cleave sequence."},
			{id=9289,title="Tanks",body="$bullet;|cFF2959D3|Hspell:156135|h[Heavy Handed]|h|r causes the Butcher to attack the player closest to his current target with a copy of all of his melee attacks. These attacks can be mitigated and avoided as usual. If another player is not close enough, the second attack will trigger on the primary target.\n$bullet;|cFF2959D3|Hspell:156151|h[The Tenderizer]|h|r will always hit. It cannot be dodged or parried, but it can be blocked.\n$bullet;|cFF2959D3|Hspell:156143|h[The Cleaver]|h|r will only apply its damage over time effect if the attack successfully lands on its target."},
			{id=8856,title="Heavy Handed",body="All of the Butcher's standard auto attacks trigger a second attack on the next closest target within 5 yards. If no target is found, the primary target is struck again."},
			{id=8857,title="The Cleaver"},
			{id=8858,title="The Tenderizer"},
			{id=10232,title="Section 15"},
			{id=8859,title="Cleave"},
			{id=8860,title="Bounding Cleave",body="When the Butcher reaches 100 Energy he begins the Bounding Cleave sequence by knocking all players back, then charging to a clump at range and cleaving targets within that clump."},
			{id=8861,title="Gushing Wounds"},
			{id=8862,title="Frenzy",body="After the Butcher reaches 30% health remaining, he Frenzies. While Frenzied the Butcher deals 10% more damage and attacks 30% faster."},
			{id=10228,title="Night-Twisted Cadaver",body="In Mythic Difficulty, Night-Twisted Cadavers will spawn and walk towards The Butcher in a final, vain attempt to slay him. When the Cadaver reaches The Butcher or when they walk near a player, they will Explode, leaving a pool of Pale Vitriol behind for the duration of the encounter.",difficultyIDs={16}},
			{id=10230,title="Paleobomb",difficultyIDs={16}},
			{id=10231,title="Section 14",difficultyIDs={16}},
		},
	},
	[1122]={
		encounterID=1122,
		instanceID=457,
		order=3,
		name="Beastlord Darmac",
		lore="As a young orc, Darmac quickly rose through the ranks of the Thunderlord as a gifted trainer of beasts. Where others only saw animal instincts, he recognized intellect and drew forth untapped potential from brain and muscle and bone. When the Iron Horde demanded his service, Darmac saw no greater honor than to outfit and train the most savage beasts Draenor had to offer.",
		dungeonEncounterID=1694,
		uiMapID=599,
		pin={x=0.6631,y=0.7218},
