	[1128]={
		encounterID=1128,
		instanceID=477,
		order=1,
		name="Kargath Bladefist",
		lore="Kargath Bladefist, Warlord of the Shattered Hand, honed his brutal skills as a slave in the ogres' gladiatorial games. He slaughtered countless opponents for the promise of freedom, but after winning, was locked away with the other retired \"champions.\" Fueled by rage, Kargath tore off his own hand to escape and led a revolt that soaked Draenor in ogre blood. Now, he returns to the arena to teach you the true meaning of savagery.",
		dungeonEncounterID=1721,
		uiMapID=612,
		pin={x=0.5476,y=0.5766},
		difficultyIDs={14,15,16,17},
		npcIDs={78714},
		displayIDs={54674},
