		sections={
			{id=9460,title="Overview",body="Sadana stands at the center of a ritual circle, calling down dark energies to assault her enemies and attempting to absorb the life force of nearby spirits to heal herself when she is injured."},
			{id=10723,title="Damage Dealers",body="$bullet;Survive Sadana's |cFF2959D3|Hspell:164686|h[Dark Eclipse]|h|r by touching the uncorrupted blue runes to gain |cFF2959D3|Hspell:162652|h[Lunar Purity]|h|r.\n$bullet;Slay Defiled Souls before Sadana can sacrifice them during |cFF2959D3|Hspell:153153|h[Dark Communion]|h|r."},
			{id=10722,title="Healers",body="$bullet;Survive Sadana's |cFF2959D3|Hspell:164686|h[Dark Eclipse]|h|r by touching the uncorrupted blue runes to gain |cFF2959D3|Hspell:162652|h[Lunar Purity]|h|r.\n$bullet;|cFF2959D3|Hspell:153093|h[Whispers of the Dark Star]|h|r deals sustained groupwide damage that must be healed through.\n$bullet;Slay Defiled Souls before Sadana can sacrifice them during |cFF2959D3|Hspell:153153|h[Dark Communion]|h|r."},
			{id=10724,title="Tanks",body="$bullet;Survive Sadana's |cFF2959D3|Hspell:164686|h[Dark Eclipse]|h|r by touching the uncorrupted blue runes to gain |cFF2959D3|Hspell:162652|h[Lunar Purity]|h|r.\n$bullet;Slay Defiled Souls before Sadana can sacrifice them during |cFF2959D3|Hspell:153153|h[Dark Communion]|h|r.\n$bullet;Sadana's |cFF2959D3|Hspell:162696|h[Death Spike]|h|r can be dodged, blocked, reflected and parried to reduce severe incoming damage."},
