			{id=9531,title="Damage Dealers",body="$bullet;Move away when |cFF2959D3|Hspell:159481|h[Siege Bombs]|h|r are fired at you.\n$bullet;Interrupt Grom'kar Firemenders' |cFF2959D3|Hspell:160140|h[Cauterizing Bolt]|h|r."},
