			{id=9533,title="Tanks",body="$bullet;Be ready to grab the attention of any reinforcement troops.\n$bullet;Take turns tanking Thogar to avoid excessive |cFF2959D3|Hspell:155921|h[Enkindle]|h|r stacks."},
