	[1153]={
		encounterID=1153,
		instanceID=477,
		order=6,
		name="Ko'ragh",
		lore="Ko'ragh was the only ogre to survive direct exposure to a mysterious relic unearthed by the Highmaul excavations of Nagrand, and was left with a near-complete immunity to all magic. Rumors abound regarding his connection to the Imperator, with some wondering why Ko'ragh would remain subservient to a sorcerer despite his unique gifts.",
		dungeonEncounterID=1723,
		uiMapID=613,
		pin={x=0.3782,y=0.6545},
		difficultyIDs={14,15,16,17},
		npcIDs={79015,87445},
		displayIDs={54825},
		loot={
			{itemID=116293,diffs={17},faction=-1},
			{itemID=116295,diffs={17},faction=-1},
			{itemID=116231,diffs={17},faction=-1},
			{itemID=113836,diffs={14,15,16},faction=-1},
			{itemID=113837,diffs={14,15,16},faction=-1},
			{itemID=113838,diffs={14,15,16},faction=-1},
			{itemID=116366,diffs={17},faction=-1},
			{itemID=116367,diffs={17},faction=-1},
			{itemID=113839,diffs={14,15,16},faction=-1},
			{itemID=116368,diffs={17},faction=-1},
			{itemID=113840,diffs={14,15,16},faction=-1},
			{itemID=113841,diffs={14,15,16},faction=-1},
			{itemID=113842,diffs={14,15,16},faction=-1},
			{itemID=113843,diffs={14,15,16},faction=-1},
			{itemID=113844,diffs={14,15,16},faction=-1},
			{itemID=116212,diffs={17},faction=-1},
			{itemID=113845,diffs={14,15,16},faction=-1},
			{itemID=113846,diffs={14,15,16},faction=-1},
			{itemID=113847,diffs={14,15,16},faction=-1},
			{itemID=115996,diffs={17},faction=-1},
			{itemID=116284,diffs={17},faction=-1},
			{itemID=116029,diffs={17},faction=-1},
			{itemID=115288,diffs={},faction=-1},
		},
		sections={
			{id=9631,title="Overview",body="Ko'ragh is protected by a Nullification Barrier that absorbs all magic damage taken. When the barrier is removed, he activates a rune that recharges it. While recharging, one player may also absorb some of the rune's energy and receive a Nullification Barrier.\n\nAs the fight progresses, an increasing amount of Overflowing Energy orbs spill from the rune and float to the ground, exploding when they land.\n\nPlayers who have a Nullification Barrier can catch and absorb Overflowing Energy to mitigate the amount of raid wide damage and prevent a lethal amount of damage from occurring.$[!16 \n\nIn Mythic difficulty, two players may enter the rune per phase of Charging.$]"},
			{id=9632,title="Damage Dealers",body="$bullet;Absorb |cFF2959D3|Hspell:161242|h[Caustic Energy]|h|r to gain a |cFF2959D3|Hspell:156803|h[Nullification Barrier]|h|r.\n$bullet;Avoid |cFF2959D3|Hspell:161612|h[Overflowing Energy]|h|r until you have a |cFF2959D3|Hspell:163134|h[Nullification Barrier]|h|r. Absorb |cFF2959D3|Hspell:161612|h[Overflowing Energy]|h|r when you do have a |cFF2959D3|Hspell:163134|h[Nullification Barrier]|h|r."},
			{id=9633,title="Healers",body="$bullet;Focus intense healing on players absorbing |cFF2959D3|Hspell:161242|h[Caustic Energy]|h|r to allow them to survive the transformation.\n$bullet;|cFF2959D3|Hspell:162185|h[Expel Magic: Fire]|h|r inflicts heavy raid wide damage and requires dispels to mitigate some of the damage.\n$bullet;|cFF2959D3|Hspell:162184|h[Expel Magic: Shadow]|h|r absorbs all healing on the raid until it is removed."},
			{id=9634,title="Tanks",body="$bullet;Tanks marked with |cFF2959D3|Hspell:162186|h[Expel Magic: Arcane]|h|r must run away from their allies and avoid the periodic explosions.\n$bullet;Volatile Anomalies will spawn periodically during the charging phase. If they are killed within a |cFF2959D3|Hspell:161328|h[Suppression Field]|h|r, they will not cast |cFF2959D3|Hspell:163466|h[Destabilize]|h|r."},
			{id=9619,title="Nullification Barrier"},
			{id=10600,title="Section 21"},
			{id=9627,title="Charging",body="When the Ko'ragh's Nullification Barrier is removed, he begins to recharge. After $160734d, the barrier is restored."},
			{id=9628,title="Caustic Energy",body="One player may enter the rune with Ko'ragh, absorbing a portion of its energy. The energy inflicts $161242s1 Arcane damage every second and reduces all healing received by $161242s3% for as long as the player remains inside of the rune. This effect pierces all immunities and damage reductions.\n\nWhen the rune powers down, the player receives their own Nullification Barrier, proportional to the amount of time spent inside the rune. The Nullification Barrier received by players can absorb up to $163134s1 Magic damage.$[!16\n\nIn Mythic difficulty, two players may enter the rune per phase of Charging.$]$[!17\n\nIn Raid Finder difficulty, five players may enter the rune per phase of Charging.$]"},
			{id=9621,title="Suppression Field"},
			{id=9629,title="Volatile Anomalies",body="While the Rune of Nullification is active, 3 Volatile Anomalies spawn every $161378t1 sec."},
			{id=9630,title="Destabilize"},
			{id=9622,title="Expel Magic"},
			{id=9624,title="Fire"},
			{id=10601,title="Section 22",difficultyIDs={16}},
			{id=9625,title="Arcane"},
			{id=9618,title="Frost"},
			{id=9623,title="Shadow"},
			{id=9626,title="Overflowing Energy",body="$[!16\n\nIn Mythic difficulty, the rate that Overflowing Energy forms is accelerated.$]"},
			{id=9730,title="Dominating Power",difficultyIDs={16}},
			{id=9731,title="Forfeit Power",difficultyIDs={16}},
		},
	},
