	[1155]={
		encounterID=1155,
		instanceID=457,
		order=2,
		name="Hans'gar and Franzok",
		lore="Hans'gar and Franzok are twin brothers raised and trained as masterful brawlers of their clan. Both carved paths of glory as warriors, but destiny had other plans. The brothers, each unwilling to slay the other in the rite of mak'gora, were banished from their clan and left for dead. They survived as outcasts in the savage wilds of Draenor, and when the Iron Horde called, these powerful warriors found a new home in the massive war machine.",
		dungeonEncounterID=1693,
		uiMapID=596,
		pin={x=0.474,y=0.7675},
		difficultyIDs={14,15,16,17},
		npcIDs={90668},
		displayIDs={53575,53576},
		loot={
			{itemID=116256,diffs={17},faction=-1},
			{itemID=116034,diffs={17},faction=-1},
			{itemID=116227,diffs={17},faction=-1},
			{itemID=113897,diffs={14,15,16},faction=-1},
			{itemID=113898,diffs={14,15,16},faction=-1},
			{itemID=113899,diffs={14,15,16},faction=-1},
			{itemID=116012,diffs={17},faction=-1},
			{itemID=113900,diffs={14,15,16},faction=-1},
			{itemID=113901,diffs={14,15,16},faction=-1},
