		sections={
			{id=9677,title="Overview",body="Ner'zhul unleashes the void upon his foes, summoning legions of shadowy minions to sweep death across the battlefield."},
			{id=10735,title="Damage Dealers",body="$bullet;When Ner'zhul performs |cFF2959D3|Hspell:154469|h[Ritual of Bones]|h|r, focus your damage on a single skeleton to break the chain.\n$bullet;Quickly move away from |cFF2959D3|Hspell:154353|h[Omen of Death]|h|r, which deals more damage the closer players remain."},
			{id=10734,title="Healers",body="$bullet;Quickly move away from |cFF2959D3|Hspell:154353|h[Omen of Death]|h|r, which deals more damage the closer players remain."},
