	[1161]={
		encounterID=1161,
		instanceID=457,
		order=4,
		name="Gruul",
		lore="Garrosh knew that the surest path to breaking the gronn lay in subjugating their great father, Gruul. Known in another time as the Dragonkiller, here Gruul has been reduced to the role of menial laborer. In a cruel mockery of the Shattered Hand's warrior tradition, his hand has been replaced with a hook to enable him to more easily haul pallets of fuel to the furnace.",
		dungeonEncounterID=1691,
		uiMapID=597,
		pin={x=0.3934,y=0.2056},
		difficultyIDs={14,15,16,17},
