		sections={
			{id=9681,title="Overview",body="Gruul attacks with massive sweeping blows that require the coordinated efforts of multiple players to withstand, and periodically enters a |cFF2959D3|Hspell:155539|h[Destructive Rampage]|h|r, ignoring all targets and continually performing |cFF2959D3|Hspell:155301|h[Overhead Smash]|h|r."},
			{id=9684,title="Damage Dealers",body="$bullet;If afflicted by |cFF2959D3|Hspell:155326|h[Petrifying Slam]|h|r, stay away from allies to avoid collateral damage when |cFF2959D3|Hspell:155530|h[Shatter]|h|r occurs.\n$bullet;Players must stand in close proximity to one another in order to share the damage from |cFF2959D3|Hspell:155080|h[Inferno Slice]|h|r."},
			{id=9683,title="Healers",body="$bullet;If afflicted by |cFF2959D3|Hspell:155326|h[Petrifying Slam]|h|r, stay away from allies to avoid collateral damage when |cFF2959D3|Hspell:155530|h[Shatter]|h|r occurs.\n$bullet;Players must stand in close proximity to one another in order to share the damage from |cFF2959D3|Hspell:155080|h[Inferno Slice]|h|r."},
			{id=9682,title="Tanks",body="$bullet;Taunt Gruul into a cluster of players in order to share the damage from |cFF2959D3|Hspell:155080|h[Inferno Slice]|h|r.\n$bullet;During |cFF2959D3|Hspell:155539|h[Destructive Rampage]|h|r, Gruul will continually use |cFF2959D3|Hspell:155301|h[Overhead Smash]|h|r, ignoring his threat on all targets.\n$bullet;In every difficulty except Raid Finder, quickly taunt Gruul away from players after |cFF2959D3|Hspell:155080|h[Inferno Slice]|h|r to stop |cFF2959D3|Hspell:155078|h[Overwhelming Blows]|h|r from hitting unintended targets."},
			{id=9686,title="Inferno Slice",body="$[!16\n\nIn Mythic difficulty, if Inferno Slice fails to hit at least 4 targets, Gruul will instantly gain 50 Rage.$]"},
			{id=9975,title="Crumbling Roar"},
			{id=9687,title="Overwhelming Blows",difficultyIDs={14,15,16}},
			{id=10159,title="Flare",difficultyIDs={16}},
