	[1162]={
		encounterID=1162,
		instanceID=457,
		order=8,
		name="Kromog",
		lore="The magnaron are mysterious in their ways, ancient and inscrutable. Miners excavating an expansion to the Foundry, in support of the Iron Horde's massive production needs, were horrified to unearth a chamber containing a living magnaron. To their astonishment, Kromog began to assist in their endeavors, and now uses his massive stone fists to hammer out the gigantic plates needed for the Iron Horde's dreadnaughts and siege machinery.",
		dungeonEncounterID=1713,
		uiMapID=596,
		pin={x=0.3324,y=0.4315},
		difficultyIDs={14,15,16,17},
		npcIDs={77692,90666},
