		sections={
			{id=9707,title="Overview",body="At 60% health, Nitrogg Thundertower retreats to his Assault Cannon at the far end of the train car. Players must reclaim Blackrock Munitions from soldiers that pour into the area, and use them destroy Nitrogg's cannon, after which they may dispatch Nitrogg directly."},
			{id=10326,title="Damage Dealers",body="$bullet;Defeat Grom'kar Boomers to loot |cFF2959D3|Hspell:160702|h[Blackrock Mortar Shells]|h|r, then enter a Blackrock Turret to heavily damage Nitrogg's Assault Cannon.\n$bullet;Take shelter behind an obstacle when targeted by Nitrogg's |cFF2959D3|Hspell:160681|h[Suppressive Fire]|h|r."},
			{id=10327,title="Healers",body="$bullet;Take shelter behind an obstacle when targeted by Nitrogg's |cFF2959D3|Hspell:160681|h[Suppressive Fire]|h|r.\n$bullet;The platform has many tight turns; be aware of your lines of sight to other party members."},
			{id=10328,title="Tanks",body="$bullet;Reinforcements continually enter the encounter area and must be tanked.\n$bullet;Take shelter behind an obstacle when targeted by Nitrogg's |cFF2959D3|Hspell:160681|h[Suppressive Fire]|h|r."},
