		sections={
			{id=9759,title="Overview",body="Nhallish raises spirits to attack his foes, calls down blasts of void energy, and periodically banishes all players to a spectral realm where they must defeat and recapture their own souls to escape."},
			{id=10729,title="Damage Dealers",body="$bullet;Defeat your spirit while afflicted by |cFF2959D3|Hspell:152979|h[Soul Shred]|h|r in order to return to the realm of the living and gain |cFF2959D3|Hspell:153033|h[Returned Soul]|h|r."},
			{id=10728,title="Healers",body="$bullet;Defeat your spirit while afflicted by |cFF2959D3|Hspell:152979|h[Soul Shred]|h|r in order to return to the realm of the living and gain |cFF2959D3|Hspell:153033|h[Returned Soul]|h|r."},
			{id=10730,title="Tanks",body="$bullet;Defeat your spirit while afflicted by |cFF2959D3|Hspell:152979|h[Soul Shred]|h|r in order to return to the realm of the living and gain |cFF2959D3|Hspell:153033|h[Returned Soul]|h|r.\n$bullet;Spirits raised from nearby barrows by |cFF2959D3|Hspell:153268|h[Exhume the Crypts]|h|r must be tanked."},
