	[1195]={
		encounterID=1195,
		instanceID=477,
		order=3,
		name="Tectus",
		lore="An ancient embodiment of the chaotic forces that shaped the terrain of Draenor, Tectus has been twisted and enslaved by the maddened Pale Orcs - who themselves barely maintain control over this imposing force of nature.",
		dungeonEncounterID=1722,
		uiMapID=610,
