		sections={
			{id=10055,title="Overview",body="Tectus cannot be killed by traditional means. He builds energy, channeling Tectonic Upheaval whenever he reaches 100. Depleting Tectus's health before the end of Upheaval shatters it into two Shards of Tectus; otherwise, Tectus heals and resumes gaining energy.\n\nEach Shard splits into four Motes of Tectus when shattered. Players must kill all eight Motes to defeat Tectus."},
			{id=10056,title="Damage Dealers",body="$bullet;Deplete Tectus' health before the end of |cFF2959D3|Hspell:162475|h[Tectonic Upheaval]|h|r.\n$bullet;Move out of the rumbling earth before the eruption of |cFF2959D3|Hspell:162518|h[Earthen Pillar]|h|r!"},
			{id=10057,title="Healers",body="$bullet;Players will take heavy damage during |cFF2959D3|Hspell:162475|h[Tectonic Upheaval]|h|r.\n$bullet;Move out of the rumbling earth before the eruption of |cFF2959D3|Hspell:162518|h[Earthen Pillar]|h|r!"},
			{id=10058,title="Tanks",body="$bullet;Face Night-Twisted Earthshapers away from other players to minimize damage from |cFF2959D3|Hspell:162968|h[Earthen Flechettes]|h|r.\n$bullet;Intercept |cFF2959D3|Hspell:162895|h[Gift of Earth]|h|r if you are not tanking Tectus.\n$bullet;Move out of the rumbling earth before the eruption of |cFF2959D3|Hspell:162518|h[Earthen Pillar]|h|r!"},
			{id=10060,title="Tectus, The Living Mountain",body="Tectus begins the battle fully formed, able to inflict full damage."},
			{id=10072,title="The Living Mountain"},
			{id=10065,title="Accretion",body="$[!16\n\nOn Mythic difficulty, if any other Shards or Motes of Tectus are within $162288A1 yds. of Tectus when he gains Accretion, they will also gain Accretion.$]"},
			{id=10067,title="Earthen Pillar",body="$[!16\n\nOn Mythic difficulty, Tectus also uses this ability at 50 Energy. $]"},
			{id=10066,title="Faultline"},
			{id=10074,title="Fracture"},
			{id=10073,title="Tectonic Upheaval"},
			{id=10828,title="Section 36",difficultyIDs={16}},
			{id=10063,title="Shard of Tectus",body="When shattered, the remnants of Tectus will form two Shards of Tectus.\n\nShards of Tectus share Tectus' abilities, but individually deal less damage."},
			{id=10076,title="Shard of the Mountain"},
			{id=10077,title="Accretion",body="$[!16\n\nOn Mythic difficulty, if any other Shards or Motes of Tectus are within $A1 yds. of Tectus when he gains Accretion, they will also gain Accretion.$]"},
			{id=10078,title="Faultline"},
			{id=10079,title="Fracture"},
			{id=10080,title="Earthen Pillar",body="$[!16\n\nOn Mythic difficulty, Tectus also uses this ability at 50 Energy. $]"},
			{id=10081,title="Tectonic Upheaval"},
			{id=10829,title="Section 37",difficultyIDs={16}},
			{id=10064,title="Mote of Tectus",body="When shattered, the remnants of each Shard of Tectus will form four Motes of Tectus.\n\nMotes of Tectus do not need to be shattered. Players are victorious over Tectus after they have killed all of the Motes of Tectus."},
			{id=10083,title="Mote of the Mountain"},
			{id=10084,title="Accretion"},
			{id=10085,title="Faultline"},
			{id=10086,title="Fracture"},
			{id=10087,title="Earthen Pillar",body="$[!16\n\nOn Mythic difficulty, Tectus also uses this ability at 50 Energy. $]"},
			{id=10088,title="Tectonic Upheaval"},
			{id=10815,title="Night-Twisted Pale",body="While Tectus is fully formed, Night-Twisted Pale will attempt to enter the fight, empowering Tectus and attacking players.\n$[!16\n\nIn Mythic difficulty, Night-Twisted pale continue to attack after Tectus is shattered.$]"},
			{id=10061,title="Night-Twisted Earthwarper"},
			{id=10068,title="Gift of Earth"},
			{id=10069,title="Petrification"},
			{id=10070,title="Earthen Flechettes"},
			{id=10062,title="Night-Twisted Berserker"},
			{id=10071,title="Raving Assault"},
		},
	},
	[1196]={
