		sections={
			{id=9976,title="Overview",body="Brackenspore emerges from the infested waters beneath the cliffs of Highmaul, spreading fungal growth that will engulf the beach if left unchecked. Players must use available Flamethrowers to keep Creeping Moss in check, while defeating hostile fungi that Brackenspore creates in his wake."},
			{id=9977,title="Tanks",body="$bullet;Grab the attention of Fungal Flesh-Eaters as they stream in from the sea.\n$bullet;Interrupt |cFF2959D3|Hspell:160013|h[Decay]|h|r which is cast by the Fungal Flesh-Eaters."},
			{id=9979,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:160013|h[Decay]|h|r which is cast by the Fungal Flesh-Eaters.\n$bullet;Intercept the damage from |cFF2959D3|Hspell:160180|h[Spore Shot]|h|r away from other players, to avoid splashing the damage."},
			{id=9978,title="Healers",body="$bullet;Heal friendly mushrooms to full to gain their effects. Once they are healed to full they will begin to wither and die at an increasing rate. Keep them healed in order to maintain their beneficial effects.\n$bullet;Heal Living Mushrooms to full to gain |cFF2959D3|Hspell:159463|h[Living Spores]|h|r in order to survive the damage caused by |cFF2959D3|Hspell:163242|h[Infesting Spores]|h|r."},
			{id=9982,title="Creeping Moss",difficultyIDs={14,15,17}},
