	[1197]={
		encounterID=1197,
		instanceID=477,
		order=7,
		name="Imperator Mar'gok",
		lore="As the grand Imperator of Highmaul, Mar'gok is descended from a long line of sorcerers who have ruled the Gorian Empire. Equal parts cunning and brutality, Mar'gok recognized the rising tide of the Iron Horde and what it would mean to oppose them. He has acquiesced to an alliance with Grommash, even as he continues to search for a way to tip the balance of power back into his favor.",
		dungeonEncounterID=1705,
		uiMapID=615,
		pin={x=0.453,y=0.7522},
		difficultyIDs={14,15,16,17},
		npcIDs={77428,83268,87443},
		displayIDs={54329},
		loot={
			{itemID=113856,diffs={14,15,16},faction=-1},
			{itemID=113857,diffs={14,15,16},faction=-1},
			{itemID=116002,diffs={17},faction=-1},
