			{itemID=113854,diffs={14,15,16},faction=-1},
			{itemID=113855,diffs={14,15,16},faction=-1},
			{itemID=116287,diffs={17},faction=-1},
			{itemID=115289,diffs={},faction=-1},
		},
		sections={
			{id=9956,title="Overview",body="Imperator Mar'gok assaults players with destructive Arcane magic and summons Arcane Aberrations to fight for him.\n\nWhen Imperator Mar'gok reaches 85%, 55% and 25% health remaining, he activates one of the runestones in his throne room, augmenting his abilities with additional effects.\n\nThe runestones activated at 55% and 25% must be awakened from their dormant state. As they charge, guards arrive to defend the Imperator as Volatile Anomalies pour from the stone.$[!16\n\nIn Mythic difficulty, Imperator Mar'gok maintains the effects of 2 runestones at once and begins to awake a new runestone at 66% and 33% health remaining.$]"},
			{id=9957,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:156238|h[Arcane Wrath]|h|r spreads to nearby allies.\n$bullet;|cFF2959D3|Hspell:156467|h[Destructive Resonance]|h|r will inflict lethal damage if triggered.\n$bullet;Arcane Aberrations inflict heavy raid wide damage as long as they are alive."},
			{id=9958,title="Healers",body="$bullet;|cFF2959D3|Hspell:156238|h[Arcane Wrath]|h|r inflicts heavy damage when it expires from a target.\n$bullet;Arcane Aberrations will inflict raid wide damage every second that they are alive.\n$bullet;|cFF2959D3|Hspell:157349|h[Force Nova]|h|r inflicts heavy damage to players as it moves over them."},
			{id=9959,title="Tanks",body="$bullet;|cFF2959D3|Hspell:159515|h[Accelerated Assault]|h|r will stack indefinitely until Imperator Mar'gok melee attacks a different target.\n$bullet;|cFF2959D3|Hspell:158605|h[Mark of Chaos]|h|r will inflict damage to allies within 35 yards when it expires.\n$bullet;Imperator Mar'gok will periodically summon Arcane Aberrations."},
			{id=9889,title="Stage One: Might of the Crown"},
			{id=9895,title="Arcane Wrath"},
			{id=9896,title="Destructive Resonance"},
			{id=9945,title="Arcane Aberration",body="Imperator Mar'gok summons an Arcane Aberration."},
			{id=9949,title="Collapsing Entity"},
			{id=9897,title="Mark of Chaos"},
			{id=9898,title="Force Nova"},
			{id=9899,title="Accelerated Assault"},
			{id=9890,title="Stage Two: Rune of Displacement",body="When Imperator Mar'gok reaches 85% health remaining, he activates the Rune of Displacement.$[!16 \n\nIn Mythic difficulty, Imperator Mar'gok begins the fight with both the Rune of Displacement and Rune of Replication active.$]"},
			{id=9900,title="Arcane Wrath: Displacement",body="In addition to Arcane Wrath's normal effects, Branded Players are unable to move more than 10 yards from the location they were marked. Attempting to leave the marked area will teleport the player back to the location they were originally marked."},
			{id=9901,title="Destructive Resonance: Displacement",body="In addition to Destructive Resonance's normal effects, it grows to twice its original size over 30 seconds."},
			{id=9946,title="Displacing Arcane Aberration",body="Imperator Mar'gok summons a Displacing Arcane Aberration."},
			{id=9953,title="Impactful Pulse"},
			{id=9902,title="Mark of Chaos: Displacement",body="In addition to Mark of Chaos' normal effects, the target is teleported to a random location."},
			{id=9903,title="Force Nova: Displacement",body="In addition to Force Nova's normal effects, it now also pushes players away as the nova moves outwards."},
			{id=9891,title="Intermission: Dormant Runestones",body="When Imperator Mar'gok reaches 55% health remaining, he begins to awaken the Rune of Fortification. The rune charges for 1 minute before releasing its power.$[!16\n\nIn Mythic difficulty, Imperator Mar'gok begins to awaken the Rune of Fortification at 66% health remaining. This causes the Rune of Replication to become dormant.$]"},
			{id=9915,title="Gorian Warmage",body="Two Gorian Warmages come to defend Imperator Mar'gok as he charges the Rune of Fortification."},
			{id=10621,title="Section 52"},
			{id=9916,title="Nether Blast"},
			{id=10852,title="Section 55",difficultyIDs={16}},
			{id=9917,title="Slow"},
			{id=9918,title="Fixate"},
			{id=9919,title="Volatile Anomaly",body="As the Rune of Fortification charges, Volatile Anomalies pour from the rune stone every $157265t1 sec."},
			{id=9920,title="Destabilize"},
			{id=9892,title="Stage Three: Rune of Fortification"},
			{id=9905,title="Arcane Wrath: Fortification",body="In addition to Arcane Wrath's normal effect, the jump range of Arcane Wrath is only decreased by 25% with each jump."},
			{id=9906,title="Destructive Resonance: Fortification",body="In addition to Destructive Resonance's normal effects, it persists for 2 minutes."},
			{id=9947,title="Fortified Arcane Aberration",body="Imperator Mar'gok summons a Fortified Arcane Aberration."},
			{id=9954,title="Fortified"},
			{id=9907,title="Mark of Chaos: Fortification",body="In addition to Mark of Chaos' normal effects, the target is rooted in place."},
			{id=9908,title="Force Nova: Fortification",body="In addition to Force Nova's normal effects, an additional nova is released every $157323t1 sec,. for $157323d."},
			{id=9893,title="Intermission: Lineage of Power",body="When Imperator Mar'gok reaches 25% health remaining, he begins to awaken the Rune of Replication. The rune charges for 1 minute before releasing its power.$[!16\n\nIn Mythic difficulty, Imperator Mar'gok begins to awaken the Rune of Replication at 33% health remaining. This causes the Rune of Displacement to become dormant.$]"},
			{id=9921,title="Gorian Reaver",body="A Gorian Reaver comes to defend Imperator Mar'gok as he charges the Rune of Replication."},
			{id=9924,title="Devastating Shockwave"},
			{id=9925,title="Crush Armor"},
			{id=9926,title="Kick to the Face"},
			{id=9922,title="Gorian Warmage",body="Two Gorian Warmages come to defend Imperator Mar'gok as he charges the Rune of Replication."},
			{id=10622,title="Section 53"},
			{id=9927,title="Nether Blast"},
			{id=10851,title="Section 54",difficultyIDs={16}},
			{id=9928,title="Slow"},
			{id=9929,title="Fixate"},
			{id=9923,title="Volatile Anomaly",body="As the Rune of Replication charges, Volatile Anomalies pour from the rune stone every $157265t1 sec."},
			{id=9930,title="Destabilize"},
			{id=9894,title="Stage Four: Rune of Replication"},
			{id=9910,title="Arcane Wrath: Replication",body="In addition to Arcane Wrath's normal effects, a second player will be Branded the first time Arcane Wrath jumps."},
			{id=9911,title="Destructive Resonance: Replication",body="In addition to Destructive Resonance's normal effects, two additional Destructive Resonances are created nearby when it detonates or expires."},
			{id=9948,title="Replicating Arcane Aberration",body="Imperator Mar'gok summons a Replicating Arcane Aberration."},
			{id=9955,title="Replicate",body="Upon death, Replicating Arcane Aberrations split into 7 Arcane Remnants."},
			{id=9912,title="Mark of Chaos: Replication",body="In addition to Mark of Chaos' normal effects, 8 Orbs of Chaos are conjured when Mark of Chaos expires. Each orb flies out from the wearer and inflicts $158648s1 Arcane damage to all players that they move through."},
			{id=9913,title="Force Nova: Replication",body="In addition to Force Nova's normal effects, players who are damaged by Force Nova will inflict $157357s1 Arcane damage to their allies within $157357A1 yards."},
		},
	},
	[1202]={
		encounterID=1202,
		instanceID=457,
		order=1,
		name="Oregorger",
		lore="The storehouses of the Blackrock Foundry, laden with heaps and pallets of unprocessed Blackrock ore, represent a grand banquet feast for the ravenous rock-eating goren who have burrowed into the chamber. Oregorger is by far the largest of the invaders, gluttony swelling his frame far beyond the size of any goren previously seen in Draenor.",
		dungeonEncounterID=1696,
		uiMapID=597,
		pin={x=0.3719,y=0.8239},
		difficultyIDs={14,15,16,17},
		npcIDs={90670},
		displayIDs={54317},
		loot={
