		sections={
			{id=9960,title="Overview",body="Oregorger draws upon his reserves of Blackrock Ore to attack his enemies. When he has spent all his Blackrock Ore, he begins rampaging around in search of new Blackrock Ore to replenish himself. Once Oregorger is sated, he stops rolling and returns to fighting."},
			{id=9961,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:156879|h[Blackrock Barrage]|h|r to prevent raidwide damage and slow Oregorger's consumption of Blackrock Ore.\n$bullet;Breaking open Ore Crates during Feeding Frenzy will leave Blackrock Ore on the ground for Oregorger to consume."},
			{id=9962,title="Healers",body="$bullet;Shielding and using damage mitigating abilities on the closest target of |cFF2959D3|Hspell:156324|h[Acid Torrent]|h|r can decrease the damage dealt to rest of the targets."},
			{id=9963,title="Tanks",body="$bullet;Position yourself to be closest in the |cFF2959D3|Hspell:156324|h[Acid Torrent]|h|r cone and use damage mitigating abilities to decrease the damage dealt to others.\n$bullet;Quickly regain threat after Oregorger leaves his Feeding Frenzy."},
			{id=9969,title="Satiated Slaughter",body="When sated, Oregorger draws upon his Ore reserve to unleash powerful attacks against his enemies."},
			{id=9971,title="Acid Torrent"},
			{id=9970,title="Retched Blackrock"},
			{id=9972,title="Explosive Shard"},
			{id=9973,title="Blackrock Barrage"},
			{id=10616,title="Section 15"},
			{id=9964,title="Feeding Frenzy",body="When his Blackrock Ore reserves have depleted, Oregorger rampages through the room, trampling all in his path as he searches for ore to eat."},
			{id=9968,title="Rolling Fury"},
			{id=9965,title="Earthshaking Collision",body="$[!16 \n\n In Mythic difficulty, these collisions also leave Unstable Slag residue at the location of the collision. Unstable Slag explodes if another collision occurs at the same location. $]"},
			{id=9966,title="Hunger Drive"},
			{id=9967,title="Unstable Slag Explosion",difficultyIDs={16}},
		},
	},
	[1203]={
		encounterID=1203,
		instanceID=457,
		order=9,
		name="The Iron Maidens",
		lore="With little opportunity to exercise her tactical brilliance under the ancient social structure of the orc clans, Gar'an was thrilled to be one of the first warriors to volunteer for naval duty under the Iron Horde. Instantly successful in battle, she was named Admiral of the Iron Horde fleet and selected Marak and Sorka as her lieutenants. Together, they are called the Iron Maidens, and have crushed any who have dared face them in battle.",
