		sections={
			{id=10405,title="Overview",body="This trio of forest protectors complement each other to overcome their foes. Life Warden Gola heals his allies with |cFF2959D3|Hspell:168082|h[Revitalize]|h|r, while Earthshaper Telu stuns players with |cFF2959D3|Hspell:427459|h[Toxic Bloom]|h|r, and Dulhu threatens players with |cFF2959D3|Hspell:427512|h[Noxious Charge]|h|r."},
			{id=10552,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:168082|h[Revitalize]|h|r restores a large amount of health if not interrupted.\n$bullet;|cFF2959D3|Hspell:427459|h[Toxic Bloom]|h|r stuns all players if not interrupted."},
			{id=10553,title="Healers",body="$bullet;|cFF2959D3|Hspell:427498|h[Torrential Fury]|h|r and |cFF2959D3|Hspell:427509|h[Terrestrial Fury]|h|r inflict constant, party-wide damage.\n$bullet;|cFF2959D3|Hspell:427512|h[Noxious Charge]|h|r inflicts significant damage on players in the target area."},
			{id=10554,title="Tanks",body="$bullet;|cFF2959D3|Hspell:168082|h[Revitalize]|h|r restores a large amount of health if not interrupted.\n$bullet;|cFF2959D3|Hspell:427459|h[Toxic Bloom]|h|r stuns all players if not interrupted.\n$bullet;|cFF2959D3|Hspell:427512|h[Noxious Charge]|h|r can be a major threat to your allies if not positioned carefully."},
			{id=10409,title="Life Warden Gola"},
			{id=10411,title="Revitalizing Water"},
