		sections={
			{id=10496,title="Overview",body="Xeri'tac begins the fight crawling around the ceiling of her cavern and periodically |cFF2959D3|Hspell:169275|h[Descending]|h|r to strike at random locations. Xeri'tac is unattackable during this initial phase, but once players have defeated 8 Toxic Spiderlings, Xeri'tac will drop down to the floor for the remainder of the encounter."},
			{id=10504,title="Damage Dealers",body="$bullet;Avoid Xeri'tac's |cFF2959D3|Hspell:169275|h[Descend]|h|r ability.\n$bullet;Toxic Spiderlings leave an area of |cFF2959D3|Hspell:169223|h[Toxic Gas]|h|r when they die.\n$bullet;Creatures that gain |cFF2959D3|Hspell:169218|h[Toxic Blood]|h|r will become more powerful the longer they are alive."},
			{id=10505,title="Healers",body="$bullet;Avoid Xeri'tac's |cFF2959D3|Hspell:169275|h[Descend]|h|r ability.\n$bullet;Creatures that gain |cFF2959D3|Hspell:169218|h[Toxic Blood]|h|r will become more powerful the longer they are alive.\n$bullet;|cFF2959D3|Hspell:169376|h[Venomous Sting]|h|r targets players at random and can be dispelled."},
			{id=10497,title="Tanks",body="$bullet;Toxic Spiderlings leave an area of |cFF2959D3|Hspell:169223|h[Toxic Gas]|h|r when they die.\n$bullet;Position Venom-Crazed Pale Ones to be struck by Xeri'tac's |cFF2959D3|Hspell:169275|h[Descend]|h|r ability to cause them to suffer significant damage.\n$bullet;Creatures that gain |cFF2959D3|Hspell:169218|h[Toxic Blood]|h|r will become more powerful the longer they are alive."},
			{id=10506,title="Stage One: The Venomous Brood",body="During the initial phase of the encounter, Xeri'tac unleashes her brood, while periodically descending to strike."},
			{id=10498,title="Section 6"},
			{id=10507,title="Stage Two: Spider Matriarch",body="Once 8 Toxic Spiderlings have fallen, Xeri'tac descends to engage her prey directly."},
