	[1210]={
		encounterID=1210,
		instanceID=556,
		order=5,
		name="Yalnu",
		lore="Ancient and inscrutable, the genesaur Yalnu was drawn to the Kirin Tor outpost in Gorgrond by strange energies radiating from the bluff. For ages the genesaur have battled their eternal foes - the magnaron, the gronn, children of stone - to a stalemate across the world of Draenor. But in these emanations, Yalnu sensed a new world, where his kind could flourish and spread unchecked.",
