		sections={
			{id=10548,title="Overview",body="Yalnu causes an array of living plants to spring up from the earth to attack players with |cFF2959D3|Hspell:428823|h[Verdant Eruption]|h|r and |cFF2959D3|Hspell:169613|h[Genesis]|h|r. Kirin Tor mages assist the party in defense of Azeroth, using powerful magic to keep Yalnu  in check, but players must protect them to keep them in the fight."},
			{id=10549,title="Damage Dealers",body="$bullet;Flourishing Ancients prevent Lady Baihu from channeling |cFF2959D3|Hspell:428746|h[Brushfire]|h|r for as long as they remain alive.\n$bullet;When Yalnu uses |cFF2959D3|Hspell:169613|h[Genesis]|h|r, step on any sprouting lashers to |cFF2959D3|Hspell:173536|h[Trample]|h|r them and prevent them from becoming full-grown."},
			{id=10550,title="Healers",body="$bullet;When Yalnu uses |cFF2959D3|Hspell:169613|h[Genesis]|h|r, step on any sprouting lashers to |cFF2959D3|Hspell:173536|h[Trample]|h|r them and prevent them from becoming full-grown.\n$bullet;|cFF2959D3|Hspell:169179|h[Colossal Blow]|h|r inflicts heavy group-wide damage.",difficultyIDs={1,2}},
			{id=28271,title="Healers",body="$bullet;When Yalnu uses |cFF2959D3|Hspell:169613|h[Genesis]|h|r, step on any sprouting lashers to |cFF2959D3|Hspell:173536|h[Trample]|h|r them and prevent them from becoming full-grown.\n$bullet;|cFF2959D3|Hspell:169179|h[Colossal Blow]|h|r inflicts heavy group-wide damage.\n$bullet;Flourishing Ancients cast |cFF2959D3|Hspell:428948|h[Vibrant Flourish]|h|r, inflicting continuous group-wide damage.",difficultyIDs={8,23}},
			{id=10551,title="Tanks",body="$bullet;|cFF2959D3|Hspell:169179|h[Colossal Blow]|h|r inflicts major damage and stuns any players who fail to avoid it.\n$bullet;When Yalnu uses |cFF2959D3|Hspell:169613|h[Genesis]|h|r, step on any sprouting lashers to |cFF2959D3|Hspell:173536|h[Trample]|h|r them and prevent them from becoming full-grown."},
			{id=10531,title="Section 1"},
			{id=28268,title="Section 21"},
