	[1211]={
		encounterID=1211,
		instanceID=557,
		order=2,
		name="Tarlna the Ageless",
		lore="It is said that before Tarlna arrived in Gorgrond, the entire region was a barren wasteland. It is said that verdant life springs up in the wake of each footstep of the ancient genesaur. It is said that the creature is immortal, renewed like a forest in the aftermath of a great blaze. Much is said of Tarlna, but little is truly known or understood.",
		uiMapID=543,
		pin={x=0.4701,y=0.8593},
		difficultyIDs={14,15,16,17},
		npcIDs={81535},
		displayIDs={55767,57232,60764},
