		sections={
			{id=10670,title="Overview",body="Tarlna attacks players with |cFF2959D3|Hspell:175973|h[Colossal Blow]|h|r and |cFF2959D3|Hspell:176001|h[Savage Vines]|h|r.\n\nHe will periodically summon sproutlings and grow them into Giant Lashers with |cFF2959D3|Hspell:175979|h[Genesis]|h|r."},
			{id=10671,title="Damage Dealers",body="$bullet;Quickly defeat Untamed Mandragoras to prevent them from overwhelming your group.\n$bullet;|cFF2959D3|Hspell:175986|h[Trample]|h|r sprouting lashers before |cFF2959D3|Hspell:175979|h[Genesis]|h|r completes to prevent Giant Lashers from spawning."},
			{id=10672,title="Healers",body="$bullet;|cFF2959D3|Hspell:175973|h[Colossal Blow]|h|r inflicts heavy group-wide damage.\n$bullet;|cFF2959D3|Hspell:176001|h[Savage Vines]|h|r root players in place."},
			{id=10673,title="Tanks",body="$bullet;Untamed Madragora and Giant Lashers spawn periodically and must be tanked.\n$bullet;|cFF2959D3|Hspell:175973|h[Colossal Blow]|h|r inflicts lethal damage to enemies in front of Tarlna."},
