		sections={
			{id=10090,title="Overview",body="Witherbark grows increasingly dehydrated as he attacks the group, consuming his stores of Aqueous Energy. When his Energy is depleted, he roots himself in the soil and calls globules of water from the nearby lake to restore his vitality. Players may destroy those Globules before they reach him to prolong this phase."},
			{id=10091,title="Damage Dealers",body="$bullet;Lead |cFF2959D3|Hspell:164294|h[Unchecked Growth]|h|r away from your allies.\n$bullet;Destroy Aqueous Globules before they can reach Witherbark."},
			{id=10092,title="Healers",body="$bullet;Lead |cFF2959D3|Hspell:164294|h[Unchecked Growth]|h|r away from your allies.\n$bullet;|cFF2959D3|Hspell:164538|h[Aqueous Burst]|h|r inflicts damage to all party members when a globule is killed."},
			{id=10093,title="Tanks",body="$bullet;Face Witherbark away from players during |cFF2959D3|Hspell:164357|h[Parched Gasp]|h|r.\n$bullet;Position Witherbark so that Aqueous Globules are unlikely to pass over |cFF2959D3|Hspell:164294|h[Unchecked Growth]|h|r.\n$bullet;Be prepared to pick up and tank any |cFF2959D3|Hspell:164556|h[Unchecked Growth]|h|r that animate."},
			{id=10095,title="Brittle Bark"},
			{id=10096,title="Parched Gasp"},
			{id=10097,title="Unchecked Growth",body="$[!2\nIn Heroic difficulty, Witherbark can continue to cast Unchecked Growth even while affected by Brittle Bark.$]"},
			{id=10098,title="Unchecked Growth",body="When touched by the life giving power of an Aqueous Globule, the Unchecked Growth uproots itself and attacks nearby players."},
			{id=10599,title="Section 11"},
			{id=10100,title="Aqueous Globules",body="Spheres of pure water form from the nearby lake and move in a line towards Witherbark. Each Aqueous Globule that reaches Witherbark restores 25 Energy."},
			{id=10101,title="Aqueous Burst"},
		},
	},
