		sections={
			{id=10102,title="Overview",body="Azzakel alternates between engaging players directly in combat and summoning reinforcements from the demon world Argus. While summoning reinforcements, Azzakel cannot be attacked and players should focus on quickly defeating the reinforcements that emerge from the portal, so that they are not overwhelmed as more demons invade."},
			{id=10103,title="Damage Dealers",body="$bullet;Do not stand too close to Blazing Tricksters to avoid |cFF2959D3|Hspell:154018|h[Conflagration]|h|r.\n$bullet;Interrupt |cFF2959D3|Hspell:154221|h[Felblast]|h|r or kill Cackling Pyromaniacs before they finish casting it.\n$bullet;Do not stand near other players while affected by |cFF2959D3|Hspell153396|h[Curtain of Flame]|h|r."},
			{id=10104,title="Healers",body="$bullet;Do not stand too close to Blazing Tricksters to avoid |cFF2959D3|Hspell:154018|h[Conflagration]|h|r.\n$bullet;Do not stand near other players while affected by |cFF2959D3|Hspell153396|h[Curtain of Flame]|h|r."},
			{id=10105,title="Tanks",body="$bullet;The Felguards summoned while Azzakel channels |cFF2959D3|Hspell:153764|h[Claws of Argus]|h|r inflict heavy melee damage and must be tanked.\n$bullet;Do not stand near players affected by |cFF2959D3|Hspell153396|h[Curtain of Flame]|h|r.\n$bullet;Do not stand too close to Blazing Tricksters to avoid |cFF2959D3|Hspell:154018|h[Conflagration]|h|r."},
			{id=10119,title="Azzakel"},
			{id=10120,title="Fel Lash"},
