		sections={
			{id=10160,title="Overview",body="Teron'gor is a powerful warlock. At 75% health, he will drain and corrupt the power of the soul of one of the ancient spirits of Auchindoun, healing to full and gaining powers of either a Demonology, Destruction, or Affliction warlock depending on which spirit he drains.$[!8\n\nIn Challenge Mode, Teron'gor will siphon all three spirits and gain a combination of their powers.$]"},
			{id=10161,title="Damage Dealers",body="$bullet;Interrupt |cFF2959D3|Hspell:156854|h[Drain Life]|h|r and |cFF2959D3|Hspell:156975|h[Chaos Bolt]|h|r.\n$bullet;Avoid standing near other players when |cFF2959D3|Hspell:156921|h[Seed of Malevolence]|h|r detonates."},
			{id=10162,title="Healers",body="$bullet;Remove |cFF2959D3|Hspell:156842|h[Corruption]|h|r and |cFF2959D3|Hspell:156964|h[Immolate]|h|r from afflicted players.\n$bullet;Do not dispel players affected by |cFF2959D3|Hspell:156954|h[Unstable Affliction]|h|r.\n$bullet;Avoid standing near other players when |cFF2959D3|Hspell:156921|h[Seed of Malevolence]|h|r detonates."},
			{id=10163,title="Tanks",body="$bullet;Interrupt |cFF2959D3|Hspell:156854|h[Drain Life]|h|r and |cFF2959D3|Hspell:156975|h[Chaos Bolt]|h|r.\n$bullet;Avoid standing near other players when |cFF2959D3|Hspell:156921|h[Seed of Malevolence]|h|r detonates."},
			{id=10164,title="Stage One: Teron'gor"},
			{id=10190,title="Teron'gor"},
			{id=10165,title="Shadowbolt"},
			{id=10166,title="Corruption"},
			{id=10167,title="Drain Life"},
			{id=10168,title="Rain of Fire"},
			{id=10677,title="Section 35",difficultyIDs={2,8,23}},
			{id=10678,title="Felborne Abyssal",body="These infernal creatures fixate on a single target and pursue them relentlessly."},
			{id=10169,title="Stage Two: Devoured Souls",body="At 75% health, Teron'gor twists and devours one of the ancient souls of Auchindoun, gaining malevolent powers directly opposed to the good deeds the Draenei heroes stood for in life.$[!8,23\n\nIn Challenge Mode and Mythic difficulty, Teron'gor siphons all three spirits and gains a combination of their powers.$]"},
			{id=10170,title="Mender Elum",body="Teron'gor corrupts the healing powers of Mender Elum, gaining powers of Affliction."},
			{id=10191,title="Teron'gor"},
