	[1262]={
		encounterID=1262,
		instanceID=557,
		order=3,
		name="Rukhmar",
		lore="Rukhmar occasionally appears as a blazing firehawk soaring through the skies high above the Spires of Arak. The origins of the great bird are unknown, though Rukhmar is venerated as a deity by the arakkoa, seen as an embodiment of the sun itself.",
		uiMapID=542,
		pin={x=0.4711,y=0.7846},
		difficultyIDs={14,15,16,17},
		npcIDs={83746,87493},
		displayIDs={59089},
		loot={
			{itemID=120112,diffs={14},faction=-1},
			{itemID=115440,diffs={14},faction=-1},
			{itemID=120113,diffs={14},faction=-1},
