		instanceID=557,
		order=1,
		name="Drov the Ruiner",
		lore="Drov was called Ruiner by the Blackrock clans of old, who quickly learned to give the fearsome magnaron a wide berth. Drov carves a swath of devastation where he walks, as though the earth itself senses his arrival and parts to make way.",
		uiMapID=543,
		pin={x=0.4413,y=0.3992},
		difficultyIDs={14,15,16,17},
		npcIDs={81252,87437},
		displayIDs={58260,60733},
