		sections={
			{id=10659,title="Overview",body="The massive magnaron smashes the earth, causing a horde of goren to burrow up from beneath the earth and sow chaos among his foes."},
			{id=10737,title="Damage Dealers",body="$bullet;Watch Drov's facing carefully to avoid |cFF2959D3|Hspell:175791|h[Colossal Slam]|h|r.\n$bullet;Avoid Frenzied Rumblers during |cFF2959D3|Hspell:175827|h[Call of Earth]|h|r until they submerge. They will re-emerge randomly and attack players."},
			{id=10738,title="Healers",body="$bullet;Drov's |cFF2959D3|Hspell:175953|h[Giga Smash]|h|r inflicts groupwide damage.\n$bullet;Watch Drov's facing carefully to avoid |cFF2959D3|Hspell:175791|h[Colossal Slam]|h|r.\n$bullet;Avoid Frenzied Rumblers during |cFF2959D3|Hspell:175827|h[Call of Earth]|h|r until they submerge. They will re-emerge randomly and attack players."},
			{id=10739,title="Tanks",body="$bullet;Watch Drov's facing carefully to avoid |cFF2959D3|Hspell:175791|h[Colossal Slam]|h|r.\n$bullet;Avoid Frenzied Rumblers during |cFF2959D3|Hspell:175827|h[Call of Earth]|h|r until they submerge. They will re-emerge randomly and attack players."},
			{id=10653,title="Section 2"},
			{id=10654,title="Section 3"},
			{id=10655,title="Section 1"},
			{id=10656,title="Rumbling Goren",body="Frenzied Goren will emerge from the ground, inflicting $175835s2 Nature damage on impact. They will roll around in a frenzy, inflicting $175920s2 Physical damage on contact and knocking players away. After Call of Earth is over these Goren will submerge back into the ground, re-emerging at will."},
			{id=10657,title="Section 5"},
			{id=10658,title="Section 6"},
		},
	},
	[1372]={
