			{id=11542,title="Section 26"},
			{id=11543,title="Section 27",body="$[!16\nIn Mythic difficulty Gorefiend's Corruption is only removed when a player collapses an Unstable Soul.$]"},
			{id=11375,title="Trapped Souls"},
			{id=11376,title="Shadowy Construct",body="The twisted remains of a soul walk towards the center of Gorefiend's stomach before being released and empowered."},
			{id=11661,title="Section 34"},
			{id=11377,title="Tortured Essence",body="A draenei spirit bound to Gorefiend's will. The spirit moves towards the center of the stomach where it will be fully corrupted and released. Healing the spirit to full releases it from Gorefiend's grasp."},
