	[1391]={
		encounterID=1391,
		instanceID=669,
		order=9,
		name="Fel Lord Zakuun",
		lore="Speculated by some scholars of the Legion to be an evolved version of the common felguard, Fel Lords serve as enforcers in the direct service of Archimonde. Their cruelty is matched only by their brute force. Zakuun was set to a task that called upon both of these traits in equal measure: breaking the iron will of a stubborn and defiant orc chieftain of the Warsong Clan....",
		dungeonEncounterID=1777,
		uiMapID=666,
		pin={x=0.4988,y=0.1829},
		difficultyIDs={14,15,16,17},
