		sections={
			{id=11091,title="Overview",body="Zakuun alternates between attacking with his axe, and flinging it to the ground to strike with his fists, modifying his abilities in the process. Throughout the encounter, Zakuun attempts to form Fel Crystals, though players may prevent this process by absorbing the energy themselves. In either case, some of Zakuun's abilities will trigger a massive explosion if they strike either a Crystal or a player with absorbed Latent Energy."},
			{id=11092,title="Tanks",body="$bullet;Stand within |cFF2959D3|Hspell:179582|h[Rumbling Fissures]|h|r to seal them when not actively tanking.\n$bullet;When the Fel Lord is |cFF2959D3|Hspell:179667|h[Disarmed]|h|r or |cFF2959D3|Hspell:179671|h[Heavily Armed]|h|r, both tanks must stand together.\n$bullet;|cFF2959D3|Hspell:179406|h[Soul Cleave]|h|r banishes you to the Shadow Realm, allowing you to shed your |cFF2959D3|Hspell:182008|h[Latent Energy]|h|r."},
			{id=11093,title="Damage Dealers",body="$bullet;Stand within |cFF2959D3|Hspell:179582|h[Rumbling Fissures]|h|r to seal them.\n$bullet;When targeted with |cFF2959D3|Hspell:181508|h[Seed of Destruction]|h|r, aim |cFF2959D3|Hspell:181499|h[Wake of Destruction]|h|r away from any |cFF2959D3|Hspell:179620|h[Fel Crystals]|h|r.\n$bullet;When |cFF2959D3|Hspell:179711|h[Befouled]|h|r, move away from your allies."},
			{id=11094,title="Healers",body="$bullet;Stand within |cFF2959D3|Hspell:179582|h[Rumbling Fissures]|h|r to seal them.\n$bullet;When targeted with |cFF2959D3|Hspell:181508|h[Seed of Destruction]|h|r, aim |cFF2959D3|Hspell:181499|h[Wake of Destruction]|h|r away from any |cFF2959D3|Hspell:179620|h[Fel Crystals]|h|r.\n$bullet;When |cFF2959D3|Hspell:179711|h[Befouled]|h|r, move away from your allies."},
			{id=11480,title="Encounter-Wide Mechanics",body="These mechanics are seen throughout the encounter:"},
			{id=11181,title="Section 17"},
			{id=11185,title="Section 21",difficultyIDs={14,15,16}},
			{id=11845,title="Section 31",difficultyIDs={17}},
			{id=11838,title="Destructive Forces",body="Some of the Fel Lord's abilities will trigger an explosion if they strike a player who has Latent Energy."},
			{id=11482,title="Section 28"},
			{id=11180,title="Section 16"},
			{id=11806,title="Section 30"},
			{id=11839,title="Fissures and Crystals",body="Zakuun creates Rumbling Fissures on the ground nearby. If a Rumbling Fissure is not absorbed by standing within it, it forms a Fel Crystal."},
			{id=11103,title="Fel Geyser",body="The last Rumbling Fissure present after any others have been absorbed will immediately transform into a Fel Crystal."},
			{id=11104,title="Fel Crystal"},
			{id=11095,title="Armed",body="At the beginning of the fight Zakuun is armed with his axe. While Armed, Zakuun swings slowly and hits a single target with his melee attacks."},
			{id=11189,title="Section 25",body="$[!16\n\nOn Mythic Difficulty, Soul Cleave hits up to $179406I targets within $179406A2 yards.  Only the primary target is afflicted with Cloven Soul; but all targets hit by Soul Cleave are Disembodied.$]"},
			{id=11190,title="Section 26",body="$[!15,16\n\nOn Heroic and Mythic Difficulties, when the victim re-enters the Mortal Realm, Wakes of Destruction are unleashed.$]\n$[!16\n\nOn Mythic Difficulty, players who had Latent Energy while Disembodied gain Exhausted Soul after Disembodied ends.$]"},
			{id=11481,title="Section 28"},
			{id=11805,title="Section 29",difficultyIDs={16}},
			{id=11843,title="Section 30"},
			{id=11837,title="Residual Energy",body="Residual Energy is left behind whenever a player leaves the Shadow Realm and will continually fire either Wakes of Destruction or Rings of Destruction."},
			{id=11096,title="Fel Swipe"},
			{id=11098,title="Befouled"},
			{id=11188,title="Section 24"},
			{id=11840,title="Disarmed",body="Zakuun hurls his axe at the target location, where it lodges in the floor and damages the raid with Fel Explosions.\n\nWhile Disarmed, Zakuun attacks with both fists, is Heavy Handed, and gains $179667s1% haste."},
			{id=11102,title="Fel Explosions"},
			{id=11842,title="Section 29"},
			{id=11105,title="Touch of Evil"},
			{id=11107,title="Enrage"},
			{id=11106,title="Heavily Armed"},
		},
	},
	[1392]={
		encounterID=1392,
		instanceID=669,
		order=3,
		name="Kormrok",
		lore="As ancient as Draenor itself, Kormrok once ruled Gorgrond, the creatures of the land slinking away from the giant magnaron's destructive fury. But then the Iron Horde came, trapping the behemoth and attempting to break his will. They were entirely unsuccessful... that is, until the rise of Gul'dan, and the fel power that Kormrok could not resist.",
		dungeonEncounterID=1787,
		uiMapID=664,
		pin={x=0.5222,y=0.4518},
