		sections={
			{id=11110,title="Overview",body="Kormrok periodically jumps to the nearest fel pool of energy, empowering one of his abilities for a short duration depending on which pool he entered."},
			{id=11111,title="Tanks",body="$bullet;Move Kormrok near the pool to which you want him to |cFF2959D3|Hspell:180068|h[Leap]|h|r.\n$bullet;Spread out during |cFF2959D3|Hspell:180244|h[Pound]|h|r."},
			{id=11112,title="Healers",body="$bullet;|cFF2959D3|Hspell:180244|h[Pound]|h|r inflicts heavy damage to the entire raid, compounded if players do not spread out.\n$bullet;Move away from any tanks affected by |cFF2959D3|Hspell:181306|h[Fiery Burst]|h|r.\n$bullet;Trigger |cFF2959D3|Hspell:181296|h[Fiery Runes]|h|r before they explode."},
			{id=11113,title="Damage Dealers",body="$bullet;Kill Crushing Hands as quickly as possible.\n$bullet;Run away from any tanks affected by |cFF2959D3|Hspell:181306|h[Fiery Burst]|h|r.\n$bullet;Trigger |cFF2959D3|Hspell:181296|h[Fiery Runes]|h|r before they explode.\n$bullet;Spread out during |cFF2959D3|Hspell:180244|h[Pound]|h|r."},
			{id=11114,title="Leap",body="$[!16\nOn Mythic Difficulty, residue is sent out from the pool that Kormrok jumped into.$]"},
			{id=11115,title="Swelling Energy",difficultyIDs={14,15,16}},
			{id=11834,title="Section 20",difficultyIDs={17}},
			{id=11116,title="Section 7",difficultyIDs={14,15,16}},
			{id=11835,title="Section 21",difficultyIDs={17}},
			{id=11117,title="Section 8",difficultyIDs={14,15,16}},
			{id=11836,title="Section 22",difficultyIDs={17}},
			{id=11737,title="Section 19",difficultyIDs={16}},
			{id=11119,title="Section 10",body="$[!14,15,16\nWhen empowered, this abiliity causes all three pools to send out globules.$]"},
			{id=11120,title="Section 11",body="$[!14,15,16\nWhen empowered, triggering the rune causes it to try and reform nearby. Explosive Runes will not reform on top of an existing Explosive Rune, nor will they reform if they are the last Explosive Rune active.$]"},
			{id=11122,title="Section 12",body="$[!14,15,16\nWhen empowered, Dragging Hands that pull players toward the closest pool are summoned instead.$]"},
			{id=11124,title="Mutating Hatred",body="Kormrok will use different abilities against his current tank target based on the last pool he leapt into.  Getting hit with any of these abilities afflicts the victim with Fel Touch."},
			{id=11125,title="Section 16"},
			{id=11126,title="Fiery Burst"},
