		},
	},
	[1394]={
		encounterID=1394,
		instanceID=669,
		order=11,
		name="Tyrant Velhari",
		lore="When Gul'dan brought his gift to the Sargerei, Velhari had already made her ambitions clear and risen through the ranks with brutal ferocity. Known to her enemies as the Tyrant, Velhari was one of the first to accept the fel touch, further enhancing her combat prowess. Velhari now bears a mockery of the holy symbol of the Naaru, signifying her conviction to the new order.",
		dungeonEncounterID=1784,
		uiMapID=668,
		pin={x=0.2936,y=0.5148},
		difficultyIDs={14,15,16,17},
		npcIDs={90269,90270},
		displayIDs={62479},
		loot={
