	[1395]={
		encounterID=1395,
		instanceID=669,
		order=12,
		name="Mannoroth",
		lore="Bloodthirsty and brutal, Mannoroth was Archimonde's most feared enforcer, until he was felled by a mighty blow from Grommash's blade. Even in death, his blood was used by Gul'dan to fuel a dark bargain with the Iron Horde and their allies. Gul'dan and his minions now seek to reanimate the shattered remains of Mannoroth, that he may continue to serve the Legion.",
		dungeonEncounterID=1795,
		uiMapID=669,
		pin={x=0.5108,y=0.4801},
		difficultyIDs={14,15,16,17},
