	[1396]={
		encounterID=1396,
		instanceID=669,
		order=5,
		name="Kilrogg Deadeye",
		lore="Kilrogg Deadeye, Warlord of the Bleeding Hollow, seized control of his clan after performing a ritual to learn of his death. With this knowledge, he led his clan fearlessly on countless campaigns, marching toward the glorious end he desires. Now, with demon blood coursing through his veins, Kilrogg awaits you in Hellfire Citadel, awaiting the moment of his death, or yours.",
		dungeonEncounterID=1786,
		uiMapID=665,
		pin={x=0.5124,y=0.335},
		difficultyIDs={14,15,16,17},
		npcIDs={80177,81926,83474,90415,91390},
		displayIDs={62425},
		loot={
			{itemID=128070,diffs={17},faction=-1},
			{itemID=128049,diffs={17},faction=-1},
			{itemID=128109,diffs={17},faction=-1},
