	[1426]={
		encounterID=1426,
		instanceID=669,
		order=1,
		name="Hellfire Assault",
		lore="With the aid of the mercenary Blackfuse company, the Iron Horde constructed devastating siege machinery in the shadow of Hellfire Citadel, to be used in the eventual assault upon Azeroth's capitals. With the tanks now retrofitted to use fel energy, Siegemaster Mar'tak awaits Gul'dan's command to begin the assault.",
		dungeonEncounterID=1778,
		uiMapID=661,
		pin={x=0.6097,y=0.4503},
