	[1432]={
		encounterID=1432,
		instanceID=669,
		order=4,
		name="Hellfire High Council",
		lore="Thousands of Iron Horde orcs accepted the blood of Mannoroth, but few grew as powerful as these three champions. Dia Darkwhisper, master of Void magic and an outcast of the Shadowmoon, rose quickly to power as the left hand of Gul'dan. Gurtogg, with his insatiable hunger for blood, emerged the victor in hundreds of trials by combat. He has met his match only once, fighting Blademaster Jubei'thos to a draw. Tainted with fel sickness, they serve Gul'dan as both Highguard and Council of War.",
		dungeonEncounterID=1798,
		uiMapID=665,
		pin={x=0.7176,y=0.6761},
		difficultyIDs={14,15,16,17},
		npcIDs={92142,92144,92146},
