		sections={
			{id=11538,title="Overview",body="Each member of the council has a special attack that they will only use below 30% health. These effects will persist until the end of the encounter."},
			{id=11539,title="Tanks",body="$bullet;When Dia Darkwhisper uses |cFF2959D3|Hspell:184657|h[Nightmare Visage]|h|r, use defensive abilities to reduce the damage you take. \n$bullet;Keep Dia Darkwhisper away from her allies, else they will gain the effects of |cFF2959D3|Hspell:184473|h[Void Haze]|h|r.\n$bullet;Move away from the impact point of Gurtogg Bloodboil's |cFF2959D3|Hspell:184366|h[Demolishing Leap]|h|r to minimize damage taken."},
			{id=11540,title="Healers",body="$bullet;Dispel Dia Darkwhisper's |cFF2959D3|Hspell:184450|h[Mark of the Necromancer]|h|r before its damage becomes lethal, but do not dispel prematurely as doing so causes the effect transfers to 2 additional targets when dispelled.\n$bullet;Use defensive abilities to maximize your chance of survival if Gurtogg Bloodboil targets you with his |cFF2959D3|Hspell:184358|h[Fel Rage]|h|r.\n$bullet;Move away from the impact point of Gurtogg Bloodboil's |cFF2959D3|Hspell:184366|h[Demolishing Leap]|h|r to minimize damage taken."},
			{id=11541,title="Damage Dealers",body="$bullet;If you are afflicted with |cFF2959D3|Hspell:184450|h[Mark of the Necromancer]|h|r when Dia Darkwhisper casts |cFF2959D3|Hspell:184652|h[Reap]|h|r, the ground beneath your position will burn for the remainder of the encounter, so position yourself carefully.\n$bullet;Use defensive abilities to maximize your chance of survival if Gurtogg Bloodboil targets you with his |cFF2959D3|Hspell:184358|h[Fel Rage]|h|r.\n$bullet;Move away from the impact point of Gurtogg Bloodboil's |cFF2959D3|Hspell:184366|h[Demolishing Leap]|h|r to minimize damage taken."},
			{id=11488,title="Blademaster Jubei'thos"},
			{id=11491,title="Section 4"},
			{id=11492,title="Section 5"},
			{id=11493,title="Section 6"},
			{id=11757,title="Section 27"},
			{id=11534,title="His Final Hour",body="Upon reaching 30% health remaining, Jubei'thos will begin to cast Wicked Strike. After his death the images of Jubei'thos will continue to haunt players, striking them from the shadows."},
			{id=11758,title="Section 26"},
			{id=11489,title="Dia Darkwhisper"},
			{id=11495,title="Section 16"},
			{id=11496,title="Section 14",difficultyIDs={14,15,16}},
			{id=11497,title="Section 17"},
			{id=11498,title="Section 8",body="$[!16\n\nIn Mythic difficulty, Mark of the Necromancer bounces to 3 targets, instead of 2. $]"},
			{id=11499,title="Section 15"},
			{id=11920,title="Section 28",difficultyIDs={16}},
			{id=11500,title="Section 18",difficultyIDs={14,15,16}},
			{id=11536,title="Her Final Hour",body="Upon reaching 30% health remaining, Dia Darkwhisper is overcome by darkness, applying Mark of the Necromancer to half of all remaining foes. In her madness, she will no longer use Reap."},
			{id=11490,title="Gurtogg Bloodboil"},
			{id=11501,title="Section 9",difficultyIDs={14,15,17}},
			{id=11759,title="Section 27",difficultyIDs={16}},
