		sections={
			{id=11573,title="Overview",body="Archimonde assaults players with the might of the Burning Legion, gaining new abilities each time his health is reduced by 15%, eventually summoning |cFF2959D3|Hspell:182225|h[Rain of Chaos]|h|r to destroy Draenor.\n\nWhen a player is launched into the air by |cFF2959D3|Hspell:183817|h[Shadowfel Burst]|h|r, their allies must catch them to avoid fatal damage.\n\nAs Archimonde |cFF2959D3|Hspell:185590|h[Desecrates]|h|r the land, players must protect themselves with the |cFF2959D3|Hspell:183943|h[Light of the Naaru]|h|r.\n\nWhen Archimonde reaches 40% health remaining, he begins to cast |cFF2959D3|Hspell:186961|h[Nether Banish]|h|r, sending players to the Twisting Nether."},
			{id=11574,title="Damage Dealers",body="$bullet;Destroy Doomfire Spirits quickly before they create too much |cFF2959D3|Hspell:182826|h[Doomfire]|h|r.\n$bullet;|cFF2959D3|Hspell:184265|h[Wrought Chaos]|h|r inflicts heavy damage if aimed towards other players.\n$bullet;|cFF2959D3|Hspell:184931|h[Shackled Torment]|h|r inflicts lethal raidwide damage if mutliple shackles are broken at once.\n$bullet;Infernal Doombringers will begin to cast |cFF2959D3|Hspell:187078|h[Hellfire]|h|r if not killed quickly."},
			{id=11575,title="Healers",body="$bullet;|cFF2959D3|Hspell:185590|h[Desecrate]|h|r inflicts increasing raidwide damage to players without |cFF2959D3|Hspell:183943|h[Light of the Naaru]|h|r.\n$bullet;|cFF2959D3|Hspell:183864|h[Shadow Blast]|h|r significantly increases Shadow damage taken by |cFF2959D3|Hspell:183828|h[Death Brand]|h|r.\n$bullet;|cFF2959D3|Hspell:184931|h[Shackled Torment]|h|r inflicts heavy raidwide damage each time it is broken."},
			{id=11576,title="Tanks",body="$bullet;|cFF2959D3|Hspell:183828|h[Death Brand]|h|r inflicts massive initial damage and periodic damage until Hellfire Deathcallers are killed.\n$bullet;|cFF2959D3|Hspell:186961|h[Nether Banish]|h|r sends tanks to the Twisting Nether along with any other players within 10 yards."},
			{id=11577,title="Stage One: The Defiler"},
			{id=11578,title="Section 6",body="$[!16 \n\nIn Mythic difficulty, Doomfire is consumed when a player comes into contact with it. This effect stacks up to $183221s1 times. When the Doomfire debuff expires, a new patch of Doomfire is created at that player's location.$]"},
			{id=11579,title="Section 7",body="$[!16 \n\nIn Mythic difficulty, Allure of Flames inflicts $183591s1 Fire damage to all players for each Doomfire that is moved.$]"},
			{id=11580,title="Section 8",body="$[!16 \n\nIn Mythic difficulty, Shadowfel Burst targets 3 players.$]"},
			{id=11581,title="Section 9"},
			{id=11582,title="Hellfire Deathcaller"},
			{id=11583,title="Section 11"},
			{id=11585,title="Demonic Art: Desecration",body="When Archimonde reaches 85% health remaining, he summons corruption that erupts from the ground."},
			{id=11586,title="Section 14"},
			{id=11588,title="Yrel"},
			{id=11589,title="Section 17"},
			{id=11658,title="Section 52"},
			{id=11590,title="Stage Two: Hand of the Legion",body="When Archimonde reaches 70% health remaining, he calls on new powers to destroy his enemies."},
			{id=11591,title="Section 25",body="$[!16 \n\nIn Mythic difficulty, the range of Unleashed Torment is limited to $185008A1 yards.$]"},
			{id=11659,title="Section 53",body="$[!16 \n\nIn Mythic difficulty, the range of Unleashed Torment is limited to $185008A1 yards.$]"},
			{id=11592,title="Section 26",body="$[!16 \n\nIn Mythic difficulty, all players become the target of either Wrought Chaos or Focused Chaos when Archimonde casts Wrought Chaos.$]",difficultyIDs={15,16}},
			{id=11630,title="Section 50",body="$[!16 \n\nIn Mythic difficulty, Allure of Flames inflicts $183591s1 Fire damage to all players for each Doomfire that is moved.$]"},
			{id=11594,title="Section 21"},
			{id=11595,title="Hellfire Deathcaller"},
			{id=11596,title="Section 23"},
			{id=11598,title="Demonic Art: Vanguard of the Legion",body="When Archimonde reaches 55% health remaining, he summons the vanguard of the Burning Legion."},
			{id=11603,title="Felborne Overfiend"},
			{id=11607,title="Dreadstalker"},
			{id=11608,title="Consume Magic"},
			{id=11599,title="Stage Three: The Twisting Nether",body="When Archimonde reaches 40% health remaining, he calls on the Twisting Nether to destroy his enemies.",difficultyIDs={14,15,17}},
			{id=11615,title="Demonic Feedback",difficultyIDs={14,15,17}},
			{id=11716,title="Section 51",body="$[!16 \n\nIn Mythic difficulty, the range of Unleashed Torment is limited to $185008A1 yards.$]",difficultyIDs={14,15,17}},
			{id=11717,title="Section 52",body="$[!16 \n\nIn Mythic difficulty, the range of Unleashed Torment is limited to $185008A1 yards.$]",difficultyIDs={14,15,17}},
			{id=11634,title="Section 51",body="$[!16 \n\nIn Mythic difficulty, all players become the target of either Wrought Chaos or Focused Chaos when Archimonde casts Wrought Chaos.$]",difficultyIDs={15}},
			{id=11622,title="Nether Portal",difficultyIDs={14,15,17}},
			{id=11719,title="Living Shadow",body="Living Shadow periodically spawn from the Nether Portal and attack players. \n\nEach time a Living Shadow spawns from a portal, the rate at which they spawn is increased.",difficultyIDs={15}},
			{id=11720,title="Section 53",difficultyIDs={15}},
			{id=11616,title="The Nether",difficultyIDs={14,15,17}},
			{id=11625,title="Shadow Storm",difficultyIDs={14,15,17}},
			{id=11936,title="Section 52",difficultyIDs={14,15,17}},
			{id=11921,title="Void Star",difficultyIDs={14,15,17}},
			{id=11922,title="Section 51",difficultyIDs={14,15,17}},
			{id=11935,title="Section 51",difficultyIDs={14,15,17}},
			{id=11761,title="Shadowed Netherwalker",difficultyIDs={14,15,17}},
			{id=11937,title="Section 53",difficultyIDs={14,15,17}},
			{id=11762,title="Section 54",difficultyIDs={14,15,17}},
			{id=11600,title="Demonic Art: Rain of Chaos",body="When Archimonde reaches 25% health remaining, he summons a massive meteor to destroy Draenor.",difficultyIDs={14,15,17}},
			{id=11617,title="Rain of Chaos",difficultyIDs={14,15,17}},
			{id=11618,title="Infernal Doombringer",body="Periodically the meteor impacts from Rain of Chaos will reform as Infernal Doombringers.",difficultyIDs={14,15,17}},
			{id=11619,title="Eternal Flames",difficultyIDs={14,15,17}},
			{id=11620,title="Hellfire",difficultyIDs={14,15,17}},
			{id=11939,title="Stage Three: The Twisting Nether",body="When Archimonde reaches 40% health remaining, he transcends. All of his enemies are drawn helplessly into the Twisting Nether, an endless, chaotic space from which few have ever returned...",difficultyIDs={16}},
