	[1447]={
		encounterID=1447,
		instanceID=669,
		order=10,
		name="Xhul'horac",
		lore="Summoned by Gul'dan from the depths of the Twisting Nether, Xhul'horac is one of most powerful of the Void Revenants - a race of parasitic void-beings that tear holes through the planes of reality, consuming and absorbing the energies and beings within. Gul'dan has twisted Xhul'horac, feeding him overwhelming Fel energy, and using his powers to tear open the portals through which he plans to rally the forces of the Burning Legion.",
		dungeonEncounterID=1800,
		uiMapID=667,
		pin={x=0.4839,y=0.5074},
