			{id=11847,title="Section 38"},
			{id=11739,title="Stage Two: Grasp of the Void",body="Xhul'horac opens the Void portal, summoning forth fellow Void creatures and drawing strength from the power of the Void."},
			{id=11684,title="Section 7"},
			{id=11685,title="Section 5"},
			{id=11688,title="Omnus"},
			{id=11700,title="Section 17"},
			{id=11689,title="Section 10"},
			{id=11690,title="Section 14"},
			{id=11714,title="Unstable Voidfiend"},
			{id=11715,title="Section 27",body="$[!16\n\nOn Mythic Difficulty, each cast of Volatile Voidstep will reduce the cast time of subsequent casts.$]"},
			{id=11807,title="Stage Three: The Shadowfel Amalgamation",body="Overwhelmed by channeling a combination of Void and Fel energies, Xhul'horac's form begins rapidly shifting between one dominated by Fel and Void magic."},
			{id=11808,title="Section 37"},
			{id=11940,title="Section 39",difficultyIDs={16}},
			{id=11941,title="Section 42",difficultyIDs={16}},
			{id=11942,title="Section 40",difficultyIDs={16}},
			{id=11943,title="Section 41",difficultyIDs={16}},
