			{id=11745,title="Section 34"},
			{id=11740,title="Stage Four: Tearing Apart",body="Xhul'horac completely absorbs the energy of both the Void and Fel portals, preventing any new creatures from coming through them, and rapidly destabilizing."},
			{id=11741,title="Section 35"},
		},
